// MemoryHe.h// Copyright © 1993-2001 by Apple Computer, Inc., all rights reserved.// Contains:	MemoryHeap class interface/*	Change History		04/07/01	[PB] operator new should throw an exception, not return NULL. 		03/01/01	Don't include Memory_AC. 		01/02/01	Update copyright.		11/09/00	[PB] Make the magic number types consistent. 		09/21/00	Change header comment type.  Cast in GetBlockType.		08/22/00	CW Pro 6: Make operator delete to go with new(MMHeapLocation). 					Remove inline keywords within class declaration. 		03/24/99	Update copyright notice.		02/22/98	friend needs class.		01/14/99	Split SearchForBlock into two functions: PlaceForBlock finds					where a new free block belongs in the tree. SearchFreeBlocks					finds a free block of the desired size or larger. 					Changed the root block size back to 0, so it will never be					used as a block, and so searches will never go down its					left (smaller) branch. Put the FreeTree block self-address					before the root block, because that's where StuffAddressAtEnd					will set it. 		11/16/98	[2284717] Add room for block address at end to FreeTree					so its constructor doesn't stomp fHugeBlockSize. */#ifndef _MEMORYHE_#define _MEMORYHE_// ACS#ifndef _MEMCNFIG_#include "MemCnfig.h"#endif#ifndef _PLATFMEM_#include "PlatfMem.h"#endif// ANSI#ifndef __STDDEF__#include <stddef.h>#endif#if qProjectBuilder	#ifndef _STDEXCEPT	#include <stdexcept>	#endif#endif//========================================================================================// CLASS MemoryHeap////		Memory allocation heap using the best fit allocation strategy.////========================================================================================class EXPORT_AC MemoryHeap// This class is not documented; it is used internally by MacApp.// You never need to use it yourself.{	//------------------------------------------------------------------------------------	// Globals	//------------------------------------------------------------------------------------public:	typedef bool (*HeapWalkProc)( const void *blk, unsigned long size, bool isObject,								  void *refCon );	enum { kHeapTypeId = 0 };		// Used internally by the MemoryHeap class.	enum { kHeapMagicNumber = 0x8765FEDC };	// Keep a list of all heaps created. Very useful for debugging.	static MemoryHeap* GetFirstHeap();protected:	static MemoryHeap*	fHeapList;	// A pointer to the first heap in a static list of heaps.#if MM_DEBUG	static const char*	kDefaultDescription;	// A private constant used in debugging.	static const char*	kDeadHeapDescription;#endif#if !qMSWindowsprivate:#elsepublic:#endif	//====================================================================================	// STRUCT BlockHeaderBits	//====================================================================================	// The fBits field of BlockHeaderBits contains five fields. The following masks are	// used to get and set the fields. The block type field is used to distinguish best fit	// blocks from chunky blocks and must be the first four bits of the last byte in fBits.	struct EXPORT_AC BlockHeaderBits	{	#ifdef MM_LITTLE_ENDIAN			// Bytes are in reverse order in a long.		enum		{			kSizeMask			= 0x00FFFFFF,		kSizeShift			= 0,			kBlockTypeMask		= 0xC0000000,		kBlockTypeShift		= 30,			kIsObjectMask		= 0x20000000,		kIsObjectShift		= 29,			kFirstBlockMask		= 0x10000000,		kFirstBlockShift	= 28,			kBusyMask			= 0x08000000,		kBusyShift			= 27,			kPreviousBusyMask	= 0x04000000,		kPreviousBusyShift	= 26,			kMagicNumberMask	= 0x03000000,		kMagicNumberShift	= 24		};	#else		enum		{			kSizeMask			= 0xFFFFFF00,		kSizeShift			= 8,			kBlockTypeMask		= 0x000000C0,		kBlockTypeShift		= 6,			kIsObjectMask		= 0x00000020,		kIsObjectShift		= 5,			kFirstBlockMask		= 0x00000010,		kFirstBlockShift	= 4,			kBusyMask			= 0x00000008,		kBusyShift			= 3,			kPreviousBusyMask	= 0x00000004,		kPreviousBusyShift	= 2,			kMagicNumberMask	= 0x00000003,		kMagicNumberShift	= 0		};	#endif		enum		{			kBlockTypeId = kHeapTypeId + 1, 			kBlockMagicNumber = 0x3		};		unsigned long fBits;		bool			GetBusy() const;		bool			GetIsFirst() const;		bool			GetIsObject() const;		unsigned long	GetMagicNumber() const;		bool			GetPreviousBusy() const;		MMSize			GetSize() const;		unsigned short	GetBlockType() const;		void SetBusy(bool busy);		void SetIsFirst(bool first);		void SetIsObject(bool isObj);		void SetPrevBusy(bool busy);		void SetSize(MMSize size);		void SetBlockType(unsigned long blockType);		void SetMagicNumber(unsigned long magicNumber);		BlockHeaderBits(unsigned long bits) : fBits(bits) {}		BlockHeaderBits(int busy, int previousBusy, long size);	};	//====================================================================================	// CLASS BlockHeader	//====================================================================================	class EXPORT_AC BlockHeader : public BlockHeaderBits	// This class is not documented; it is used internally by the MemoryHeap	// class. You never need to use it yourself.	{	public:		BlockHeader(int busy, int prevBusy, long size);		BlockHeader(const BlockHeader& otherBlock);		bool operator >(const BlockHeader& blk) const;		bool operator <(const BlockHeader& blk) const;		bool operator >=(const BlockHeader& blk) const;		bool operator <=(const BlockHeader& blk) const;		bool operator ==(const BlockHeader& blk) const;		bool operator !=(const BlockHeader& blk) const;		BlockHeader& operator=(const BlockHeader& blk);#if __MWERKS__ >= 0x2400		void operator delete(void* /*ptr*/, void*) { };#endif		void operator delete(void* /*ptr*/) { };		void* operator new(size_t aSize, void* ptr);		void* operator new(size_t aSize);		BlockHeader* GetNextBlock() const;				MMSize GetAllocatedSize() const;	};	//====================================================================================	// CLASS Block	//====================================================================================	class Block : public BlockHeader	// This class is not documented; it is used internally by the MemoryHeap	// class. You never need to use it yourself.	{	public:		Block(int prevBusy, long size, MemoryHeap* heapPtr);		Block(const Block& otherBlock);		Block& operator =(const Block& blk);		MemoryHeap* GetHeap() const;		void SetHeap(MemoryHeap* heapPtr);		static const Block* GetBlock(const void* contents);		static Block* GetBlock(void* contents);		const void* GetContents() const;		void* GetContents();	private:		MemoryHeap* fHeap;	};	//====================================================================================	// CLASS FreeBlock	//====================================================================================	class EXPORT_AC FreeBlock : public BlockHeader	// This class is not documented; it is used internally by the MemoryHeap	// class. You never need to use it yourself.	{	public:		FreeBlock(int prevBusy, long size);		FreeBlock(const FreeBlock& otherBlock);		FreeBlock& operator =(const FreeBlock& blk);		FreeBlock*	GetLeft() const;		FreeBlock*	GetParent() const;		FreeBlock*	GetRight() const;		void SetLeft(FreeBlock* left);		void SetParent(FreeBlock* parent);		void SetRight(FreeBlock* right);		void StuffAddressAtEnd();		FreeBlock* GetPreviousBlock() const;		void Append(FreeBlock* next);	private:		// The following fields are only present in free blocks. They are used to link the free		// block into the free block tree. The address of a free block is also stored at the end		// of the block and must be accounted for in the minimum block size.		FreeBlock* fParent;		FreeBlock* fLeft;		FreeBlock* fRight;	};	//====================================================================================	// CLASS Segment	//	//		The MemoryHeap allocates memory from the system in segments. The segments are	//		linked together in a list so that When the heap is destroyed all segments can be	//		freed.	//	//====================================================================================	class Segment	// This class is not documented; it is used internally by the MemoryHeap	// class. You never need to use it yourself.	{	public:		friend class MemoryHeap;		enum		{			kSegmentPrefixSize = 12,			kSegmentSuffixSize = 4,			kSegmentOverhead = kSegmentPrefixSize + kSegmentSuffixSize		};		FreeBlock* InitSegment(unsigned long size, Segment* nextSegment,							   MemoryHeap* heapPtr);		bool AddressInSegment(const void* ptr);		bool CheckSegment(HeapWalkProc walkerProc, void* refCon, MMSize blockHeaderSize);	#if MM_DEBUG		MMBoolean FindBlockContaining( const void* start, const void* end,							const void*& blockStart, const void*& blockEnd ) const;	#endif	private:		void* fSegmentSpace;		unsigned long fSegmentSize;		Segment* fNextSegment;				Segment(const Segment& blk);		Segment& operator =(const Segment& blk);			// This class shouldn't be copied.	};	//====================================================================================	// CLASS FreeTree	//	//		Binary tree for storing free blocks. Dependent on the structure and	//		implementation of FreeBlock.	//====================================================================================	class EXPORT_AC FreeTree	// This class is not documented; it is used internally by the MemoryHeap	// class. You never need to use it yourself.	{	public:		FreeTree();		FreeTree(const FreeTree& blk);		FreeTree& operator =(const FreeTree& blk);		void AddBlock(FreeBlock* blk);		void TreeInfo(unsigned long& bytesFree,					  unsigned long& numberOfNodes) const;		Block* RemoveBlock(FreeBlock* blk);		FreeBlock* PlaceForBlock(const FreeBlock* blk);		FreeBlock* SearchFreeBlocks(MMSize size);		const FreeBlock* FindLargestBlock() const;	#if MM_DEBUG		void CheckTree() const;		void PrintTree() const;	#endif	protected:		FreeBlock* GetSuccessorBlk(const FreeBlock* blk) const;		void TreeInfoHelper(const FreeBlock* blk,							unsigned long& bytesFree,							unsigned long& numberOfNodes) const;	#if MM_DEBUG		void CheckTreeHelper(const FreeBlock* blk) const;		void PrintTreeHelper(const FreeBlock* blk, int level = 0) const;	#endif	private:		BlockHeader*	fAddress;	// Room for block self address. It goes before the									// root, because the size of the root block is 0. 		FreeBlock		fRoot;		// Root of the tree of free blocks. 	};	//====================================================================================	// CLASS MemoryHeap	//====================================================================================public:	enum	{		kBusyOverhead = sizeof(Block),			// The overhead for allocated blocks is just the flag bits and the heap pointer. 		kMinBlockSize = sizeof(FreeTree), 			// The minimum block size is one that can hold the free block links plus			// the block self address at its end. #ifdef BUILD_WIN16		kMaxBlockSize = 60L * 1024L			// Block size limited by 64K limit of far pointers. 			// Allow 4K for overhead in the various layers.#else		kMaxBlockSize = 0x00FFFFFF			// Block size limited by BlockHeaderBits::kSizeMask. #endif	};	MemoryHeap(unsigned long sizeInitial,			   unsigned long sizeIncrement = 0,			   unsigned long hugeBlockSize = 0,		// "0" means sizeIncrement/2			   MMHeapLocation = kMMTempMemory);	virtual ~MemoryHeap();	void IMemoryHeap();	void* operator new(size_t size, MMHeapLocation = kMMTempMemory);#if __MWERKS__ >= 0x2400	void operator delete(void* ptr, MMHeapLocation);#endif	void operator delete(void* ptr);	//------------------------------------------------------------------------------------	// The Essentials	//------------------------------------------------------------------------------------	virtual void* Allocate(MMSize size);	virtual void* Reallocate(void* ptr, MMSize newSize);	virtual void Free(void* ptr);		//------------------------------------------------------------------------------------	// Block Functions	//------------------------------------------------------------------------------------		virtual MMSize BlockSize(const void* ptr) const;	MemoryHeap* GetBlockHeap(const void* ptr) const;	// Should be static but can't be made so	void SetBlockIsObject( void* ptr, bool isObject );	bool BlockIsObject( const void* ptr ) const;#if MM_DEBUG	// Debugging	bool IsValidBlock(const void* ptr) const;	bool IsMyBlock(const void* ptr) const;#endif	//------------------------------------------------------------------------------------	// Heap Functions	//------------------------------------------------------------------------------------		void Reset();	unsigned long BytesAllocated() const;	unsigned long BytesFree() const;	unsigned long HeapSize() const;	unsigned long LargestFreeBlock() const;	unsigned long NumberAllocatedBlocks() const;	MMBoolean AllocateSlushFund( size_t size, size_t allocSizeLimit );	size_t GetSlushFundSize() const	{ return fSlushFundSize; }	size_t FreeSlushFund();				// returns size freed	MMHeapLocation GetLocation() const	{ return fMemSource; }	MemoryHeap* GetNextHeap() const;	bool GetZapOnAllocate() const;	void SetZapOnAllocate(bool zapIt = false);	bool GetZapOnFree() const;	void SetZapOnFree(bool zapIt = false);#if MM_DEBUG	// Debugging	const char* GetDescription() const;	void SetDescription(const char* description = kDefaultDescription);	bool GetAutoValidation() const;	void SetAutoValidation(bool validate = false);	MMBoolean FindBlockContaining( const void* start, const void* end,								   const void*& blockStart, const void*& blockEnd ) const;	virtual void Check(HeapWalkProc proc = NULL, void* refCon = NULL ) const;	virtual void Print(char* msg = "") const;#endif	//------------------------------------------------------------------------------------	// Internal Implementation	//------------------------------------------------------------------------------------protected:	virtual void* AllocateRawMemory(MMSize size);	virtual void FreeRawMemory(void* ptr);#if MM_DEBUG	static const Block* ValidBlock(const void* ptr);	void ValidateAndReport(const void* ptr) const;#endif#if MM_DEBUG	MMBoolean ValidateMagicNumber( ) const;#else	void ValidateMagicNumber( ) const{ }#endif	//------------------------------------------------------------------------------------	// Old BestFitHeap Functions	//------------------------------------------------------------------------------------public:	void ExpandHeap(unsigned long sizeInitial, unsigned long sizeIncrement);		long GetSizeIncrement()	{ return fSizeIncrement; }	long GetHugeBlockSize()	{ return fSizeIncrement; }	protected:	void* DoAllocate(MMSize size, MMSize& allocatedSize);	void DoFree(void* ptr);	void AddToFreeBlocks(BlockHeader* blk);	FreeBlock* Coalesce(BlockHeader* blk);	FreeBlock* CreateNewSegment(unsigned long size);	void DeleteSegment( Segment* seg );	void DeleteSegments();	void GrowHeap(unsigned long sizeIncrement);	Block* RemoveFromFreeBlocks(FreeBlock* blk);	FreeBlock* SearchFreeBlocks(MMSize size);#if MM_DEBUG	virtual void CompilerCheck();#endif	//------------------------------------------------------------------------------------	// Data Members	//------------------------------------------------------------------------------------private:	MemoryHeap*		fNextHeap;			// A private field used internally to maintain a static list of heaps.	MMHeapLocation	fMemSource;			// 	bool			fZapOnAllocate;		// When this flag is true, the Allocate function will zero each new memory block it allocates.	bool			fZapOnFree;			// When this flag is true, the Free function will zero each memory block it frees.#if MM_DEBUG	bool			fAutoValidation;	// true if auto-validation is turned on. This causes the function ValidateAndReport to be called each time the Free and BlockSize functions are invoked. Used in debugging.#endif	unsigned long	fBytesAllocated;	// The number of bytes allocated.	unsigned long	fNumberAllocatedBlocks; // The number of blocks allocated.	unsigned long	fMagicNumber;		// 	MMBlock			fSlushFund;			// 	size_t			fSlushFundSize;		// 	size_t			fSlushFundAllocSizeLimit;	// Max request size to use slush fund for#if MM_DEBUG	enum { kDescriptionLength = 64 };	// Used internally by the MemoryHeap class.	char fDescription[kDescriptionLength];	// A private field used in debugging.#endif	Segment*		fSegments;			// Head of a linked list of allocated segments.	unsigned long	fSizeIncrement;		// The number of bytes by which this heap										// should be grown, should that become necessary.	unsigned long	fSizeInitial;		// The initial size of this heap, in bytes.	unsigned long	fHugeBlockSize;		// The size, in bytes, of a huge block.	FreeTree		fFreeTree;			// The root of a binary tree of free blocks. Each										// node in the tree is a BestFitBlock.	enum{ kMaxHugeBlockSize = 65535L };		MemoryHeap(const MemoryHeap& blk);	MemoryHeap& operator =(const MemoryHeap& blk);		// This class shouldn't be copied.};//========================================================================================// CLASS MemoryHeap::BlockHeaderBits//========================================================================================//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::GetBusy//----------------------------------------------------------------------------------------inline bool MemoryHeap::BlockHeaderBits::GetBusy() const{	return (fBits & kBusyMask) != 0;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::GetIsFirst//----------------------------------------------------------------------------------------inline bool MemoryHeap::BlockHeaderBits::GetIsFirst() const{	return (fBits & kFirstBlockMask) != 0;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::GetIsObject//----------------------------------------------------------------------------------------inline bool MemoryHeap::BlockHeaderBits::GetIsObject() const{	return (fBits & kIsObjectMask) != 0;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::GetMagicNumber//----------------------------------------------------------------------------------------inline unsigned long MemoryHeap::BlockHeaderBits::GetMagicNumber() const{	return (fBits & kMagicNumberMask) >> kMagicNumberShift;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::GetPreviousBusy//----------------------------------------------------------------------------------------inline bool MemoryHeap::BlockHeaderBits::GetPreviousBusy() const{	return (fBits & kPreviousBusyMask) != 0;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::GetSize//----------------------------------------------------------------------------------------inline MMSize MemoryHeap::BlockHeaderBits::GetSize() const{	return (fBits & kSizeMask) >> kSizeShift;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::GetBlockType//----------------------------------------------------------------------------------------inline unsigned short MemoryHeap::BlockHeaderBits::GetBlockType() const{	return static_cast<unsigned short>((fBits & kBlockTypeMask) >> kBlockTypeShift);}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::SetBusy//----------------------------------------------------------------------------------------inline void MemoryHeap::BlockHeaderBits::SetBusy(bool busy){	if (busy)		fBits |=  kBusyMask;	else		fBits &= ~kBusyMask;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::SetIsFirst//----------------------------------------------------------------------------------------inline void MemoryHeap::BlockHeaderBits::SetIsFirst(bool first){	if (first)		fBits |=  kFirstBlockMask;	else		fBits &= ~kFirstBlockMask;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::SetIsObject//----------------------------------------------------------------------------------------inline void MemoryHeap::BlockHeaderBits::SetIsObject(bool isObj){	if (isObj)		fBits |=  kIsObjectMask;	else		fBits &= ~kIsObjectMask;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::SetPrevBusy//----------------------------------------------------------------------------------------inline void MemoryHeap::BlockHeaderBits::SetPrevBusy(bool busy){	if (busy)		fBits |= kPreviousBusyMask;	else		fBits &= ~kPreviousBusyMask;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::SetSize//----------------------------------------------------------------------------------------inline void MemoryHeap::BlockHeaderBits::SetSize(MMSize size){	fBits &= ~kSizeMask;	fBits |= (size << kSizeShift) & kSizeMask;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::SetBlockType//----------------------------------------------------------------------------------------inline void MemoryHeap::BlockHeaderBits::SetBlockType(unsigned long blockType){	fBits &= ~kBlockTypeMask;	fBits |= (blockType << kBlockTypeShift) & kBlockTypeMask;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeaderBits::SetMagicNumber//----------------------------------------------------------------------------------------inline void MemoryHeap::BlockHeaderBits::SetMagicNumber(unsigned long magicNumber){	fBits &= ~kMagicNumberMask;	fBits |= (magicNumber << kMagicNumberShift) & kMagicNumberMask;}//========================================================================================// CLASS MemoryHeap::BlockHeader//========================================================================================//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeader::operator new//----------------------------------------------------------------------------------------inline void* MemoryHeap::BlockHeader::operator new(size_t /*size*/, void* ptr){	return ptr;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeader::operator new//----------------------------------------------------------------------------------------inline void* MemoryHeap::BlockHeader::operator new(size_t /*size*/){	// BlockHeader is intended to be allocated only with placement new. #if !qProjectBuilder	ThrowLogicError_AC();	return NULL;#else	throw logic_error("allocating BlockHeader dynamically");#endif}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeader::operator >=//----------------------------------------------------------------------------------------inline bool MemoryHeap::BlockHeader::operator >=(const MemoryHeap::BlockHeader& blk) const{	return *this > blk || *this == blk;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeader::operator <=//----------------------------------------------------------------------------------------inline bool MemoryHeap::BlockHeader::operator <=(const MemoryHeap::BlockHeader& blk) const{	return *this < blk || *this == blk;}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeader::operator !=//----------------------------------------------------------------------------------------inline bool MemoryHeap::BlockHeader::operator !=(const MemoryHeap::BlockHeader& blk) const{	return !(*this == blk);}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeader::operator =//----------------------------------------------------------------------------------------inline MemoryHeap::BlockHeader& MemoryHeap::BlockHeader::operator =(const MemoryHeap::BlockHeader& blk){	fBits = blk.fBits;	return (*this);}//----------------------------------------------------------------------------------------// MemoryHeap::BlockHeader::GetAllocatedSize//----------------------------------------------------------------------------------------inline MMSize MemoryHeap::BlockHeader::GetAllocatedSize() const{	return GetSize() - sizeof(Block);}//========================================================================================// CLASS MemoryHeap::Block//========================================================================================//----------------------------------------------------------------------------------------// MemoryHeap::Block::operator =//----------------------------------------------------------------------------------------inline MemoryHeap::Block& MemoryHeap::Block::operator =(const MemoryHeap::Block& blk){	fBits = blk.fBits;	fHeap = blk.fHeap;	return (*this);}//----------------------------------------------------------------------------------------// MemoryHeap::Block::GetHeap//----------------------------------------------------------------------------------------inline MemoryHeap* MemoryHeap::Block::GetHeap() const{#if MM_DEBUG	MM_ASSERT(GetBusy());#endif	return fHeap;}//----------------------------------------------------------------------------------------// MemoryHeap::Block::SetHeap//----------------------------------------------------------------------------------------inline void MemoryHeap::Block::SetHeap(MemoryHeap* heap){#if MM_DEBUG	MM_ASSERT(GetBusy());#endif	fHeap = heap;}//----------------------------------------------------------------------------------------// MemoryHeap::Block::GetBlock//----------------------------------------------------------------------------------------inline const MemoryHeap::Block* MemoryHeap::Block::GetBlock(const void* contents){	return reinterpret_cast<Block*>((MMBytePtr) contents - sizeof(Block));}//----------------------------------------------------------------------------------------// MemoryHeap::Block::GetBlock//----------------------------------------------------------------------------------------inline MemoryHeap::Block* MemoryHeap::Block::GetBlock(void* contents){	return reinterpret_cast<Block*>((MMBytePtr) contents - sizeof(Block));}//----------------------------------------------------------------------------------------// MemoryHeap::Block::GetContents//----------------------------------------------------------------------------------------inline const void* MemoryHeap::Block::GetContents() const{	return reinterpret_cast<void*>((MMBytePtr) this + sizeof(Block));}//----------------------------------------------------------------------------------------// MemoryHeap::Block::GetContents//----------------------------------------------------------------------------------------inline void* MemoryHeap::Block::GetContents(){	return reinterpret_cast<void*>((MMBytePtr) this + sizeof(Block));}//========================================================================================// CLASS MemoryHeap::FreeBlock//========================================================================================//----------------------------------------------------------------------------------------// MemoryHeap::FreeBlock::GetLeft//----------------------------------------------------------------------------------------inline MemoryHeap::FreeBlock* MemoryHeap::FreeBlock::GetLeft() const{	return fLeft;}//----------------------------------------------------------------------------------------// MemoryHeap::FreeBlock::GetParent//----------------------------------------------------------------------------------------inline MemoryHeap::FreeBlock* MemoryHeap::FreeBlock::GetParent() const{	return fParent;}//----------------------------------------------------------------------------------------// MemoryHeap::FreeBlock::GetRight//----------------------------------------------------------------------------------------inline MemoryHeap::FreeBlock* MemoryHeap::FreeBlock::GetRight() const{	return fRight;}//----------------------------------------------------------------------------------------// MemoryHeap::FreeBlock::SetLeft//----------------------------------------------------------------------------------------inline void MemoryHeap::FreeBlock::SetLeft(MemoryHeap::FreeBlock* left){	fLeft = left;}//----------------------------------------------------------------------------------------// MemoryHeap::FreeBlock::SetParent//----------------------------------------------------------------------------------------inline void MemoryHeap::FreeBlock::SetParent(MemoryHeap::FreeBlock* parent){	fParent = parent;}//----------------------------------------------------------------------------------------// MemoryHeap::FreeBlock::SetRight//----------------------------------------------------------------------------------------inline void MemoryHeap::FreeBlock::SetRight(MemoryHeap::FreeBlock* right){	fRight = right;}//========================================================================================// CLASS MemoryHeap::Segment//========================================================================================//----------------------------------------------------------------------------------------// MemoryHeap::Segment::AddressInSegment//----------------------------------------------------------------------------------------inline bool MemoryHeap::Segment::AddressInSegment(const void* ptr){	return ptr >= fSegmentSpace &&		   ptr <= reinterpret_cast<void*>((MMBytePtr) fSegmentSpace + fSegmentSize);}//----------------------------------------------------------------------------------------// MemoryHeap::GetFirstHeap//----------------------------------------------------------------------------------------inline MemoryHeap *MemoryHeap::GetFirstHeap(){	return fHeapList;}//----------------------------------------------------------------------------------------// MemoryHeap::BytesAllocated//----------------------------------------------------------------------------------------inline unsigned long MemoryHeap::BytesAllocated() const{	ValidateMagicNumber();	return fBytesAllocated;}#if MM_DEBUG//----------------------------------------------------------------------------------------// MemoryHeap::GetAutoValidation (MM_DEBUG only)//----------------------------------------------------------------------------------------inline bool MemoryHeap::GetAutoValidation() const{	ValidateMagicNumber();	return fAutoValidation;}#endif#if MM_DEBUG//----------------------------------------------------------------------------------------// MemoryHeap::SetAutoValidation (MM_DEBUG only)//----------------------------------------------------------------------------------------inline void MemoryHeap::SetAutoValidation(bool autoValidation){	ValidateMagicNumber();	fAutoValidation = autoValidation;}#endif#if MM_DEBUG//----------------------------------------------------------------------------------------// MemoryHeap::GetDescription (MM_DEBUG only)//----------------------------------------------------------------------------------------inline const char *MemoryHeap::GetDescription() const{	ValidateMagicNumber();	return fDescription;}#endif//----------------------------------------------------------------------------------------// MemoryHeap::GetNextHeap//----------------------------------------------------------------------------------------inline MemoryHeap *MemoryHeap::GetNextHeap() const{	return fNextHeap;}//----------------------------------------------------------------------------------------// MemoryHeap::GetZapOnAllocate//----------------------------------------------------------------------------------------inline bool MemoryHeap::GetZapOnAllocate() const{	ValidateMagicNumber();	return fZapOnAllocate;}//----------------------------------------------------------------------------------------// MemoryHeap::SetZapOnAllocate//----------------------------------------------------------------------------------------inline void MemoryHeap::SetZapOnAllocate(bool zapOnAllocate){	ValidateMagicNumber();	fZapOnAllocate = zapOnAllocate;}//----------------------------------------------------------------------------------------// MemoryHeap::GetZapOnFree//----------------------------------------------------------------------------------------inline bool MemoryHeap::GetZapOnFree() const{	ValidateMagicNumber();	return fZapOnFree;}//----------------------------------------------------------------------------------------// MemoryHeap::SetZapOnFree//----------------------------------------------------------------------------------------inline void MemoryHeap::SetZapOnFree(bool zapOnFree){	ValidateMagicNumber();	fZapOnFree = zapOnFree;}//----------------------------------------------------------------------------------------// MemoryHeap::NumberAllocatedBlocks//----------------------------------------------------------------------------------------inline unsigned long MemoryHeap::NumberAllocatedBlocks() const{	ValidateMagicNumber();	return fNumberAllocatedBlocks;}//----------------------------------------------------------------------------------------// MemoryHeap::RemoveFromFreeBlocks//----------------------------------------------------------------------------------------inline MemoryHeap::Block* MemoryHeap::RemoveFromFreeBlocks(MemoryHeap::FreeBlock* blk){	return fFreeTree.RemoveBlock(blk);}//----------------------------------------------------------------------------------------// MemoryHeap::SearchFreeBlocks//----------------------------------------------------------------------------------------inline MemoryHeap::FreeBlock* MemoryHeap::SearchFreeBlocks(MMSize size){	// block size should already be even	return fFreeTree.SearchFreeBlocks(size);}#endif // _MEMORYHE_